css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .88); position: relative; }
.loader .drum { position: absolute; bottom: 0; left: 8%; width: 84%; height: 44%; overflow: hidden; border-radius: 46% 46% 8px 8px; background: color-mix(in srgb, #000 32%, var(--accent-2)); }
.loader .drum::after { content: ''; position: absolute; top: 50%; left: 50%; width: calc(var(--loader-size) * 1.4); height: calc(var(--loader-size) * 1.4); margin: calc(var(--loader-size) * -.7) 0 0 calc(var(--loader-size) * -.7); border-radius: 50%; background: repeating-conic-gradient(from 0deg, rgba(255, 255, 255, .16) 0 9deg, transparent 9deg 20deg); animation: drum-spin calc(var(--loader-speed) * .8) linear infinite; }
.loader::after { content: ''; position: absolute; bottom: 30%; left: 48%; width: 4%; height: 28%; border-radius: 2px; background: #f1f5f9; }
.loader span { position: absolute; bottom: 44%; left: 30%; width: 40%; height: 48%; border-radius: 52% 52% 42% 42%; background: radial-gradient(circle at 38% 32%, color-mix(in srgb, #fff 52%, var(--accent)), var(--accent)); animation: fluff calc(var(--loader-speed) * 2.6) ease-in-out infinite; }
@keyframes drum-spin { to { transform: rotate(360deg); } }
@keyframes fluff { 0% { opacity: .25; transform: scale(.32); } 68% { opacity: 1; transform: scale(1); } 84% { transform: scale(1.05); } 100% { opacity: .25; transform: scale(.32); } }
